var e={"profile.title":`Votre pseudo`,"profile.desc":`Utilisé quand vos messages web sont copiés sur Telegram (pas affiché sous vos messages dans les sessions).`,"profile.name":`Nom`,"profile.nameDesc":`32 caractères au plus. Vide : pas de pseudo.`,"profile.namePlaceholder":`ex. Alex`,"profile.photo":`Photo`,"profile.photoDesc":`Affichée à la place de la couleur et de l'emoji, ici et chez vos contacts Team. Gardée sur ce serveur.`,"profile.photoError":`Cette image ne peut pas être lue ici : essayez un JPEG ou un PNG.`,"profile.photoAdd":`Ajouter une photo`,"profile.photoChange":`Changer`,"profile.photoRemove":`Retirer`,"profile.color":`Couleur`,"profile.colorDesc":`La couleur de votre badge (sans photo).`,"profile.emoji":`Emoji`,"profile.emojiDesc":`Affiché dans votre badge à la place de vos initiales (facultatif, sans photo).`,"profile.preview":`Aperçu`,"profile.previewText":`Salut ! Prêt quand tu veux.`,"profile.you":`Vous`,"register.desc":`Tout est facultatif. Ce que ce serveur dit aux auteurs de Harness Maxxing, et comment arrêter.`,"register.email":`E-mail (facultatif)`,"register.emailPlaceholder":`vous@exemple.com`,"register.emailDesc":`Seulement pour vous prévenir d'un problème de sécurité ou d'un changement important. Jamais partagé, jamais vendu.`,"register.emailInvalid":`Ça ne ressemble pas à une adresse e-mail.`,"register.news":`M'envoyer aussi les nouveautés`,"register.newsDesc":`Les nouvelles fonctionnalités, quelques fois par mois au plus. Désinscription ici à tout moment.`,"register.count":`Aider à compter les installations (anonyme)`,"register.countDesc":`Une fois par jour : un numéro tiré au hasard, la version, le système (ex. Ubuntu 24.04, x86_64) et quelques codes de santé (service actif, Claude connecté, dernière mise à jour ratée…). Ni nom, ni e-mail, ni IP, ni nom de serveur, ni contenu.`,"register.countBlocked":`Désactivé sur ce serveur par MAXXING_NO_TELEMETRY ou DO_NOT_TRACK dans l'environnement du service.`,"register.privacy":`Envoyé à api.harness-maxxing.com. Votre pseudo et votre langue ne partent qu'avec un e-mail. Tout décocher arrête tout : nous ne contactons plus ce serveur.`,"register.statusOff":`Ce serveur ne dit rien aux auteurs.`,"register.statusOn":`Enregistré. Un signal par jour.`,"register.statusPending":`Pas encore envoyé : ce sera fait au prochain signal quotidien.`,"register.statusError":`Impossible de joindre les auteurs : {error}. Nouvel essai demain.`,"register.stop":`Arrêter, ne plus être contacté`,"license.title":`Licence Entreprise (facultative)`,"license.desc":`Harness Maxxing est gratuit pour vous-même et pour une organisation qui l'utilise pour ses propres besoins. Une clé ne sert qu'aux entreprises qui en ont besoin ; elle ne change rien au fonctionnement.`,"license.read":`Lire la licence`,"license.whoTitle":`Qui a besoin d'une clé ?`,"license.who1":`Une organisation qui l'utilise pour ses filiales, les sociétés de son groupe ou ses clients.`,"license.who2":`Une offre payante qui l'inclut : revente, hébergement, installation ou support payants.`,"license.whoNot":`Personne d'autre : particuliers, indépendants et organisations pour leurs propres besoins n'ont rien à faire.`,"license.get":`Demander une licence Entreprise`,"license.key":`Clé de licence`,"license.keyDesc":`Vérifiée par harness-maxxing.com (une clé = un serveur). Rien d'autre ne change : les mises à jour viennent toujours de GitHub.`,"license.invalid":`Une clé ressemble à HM-XXXX-XXXX-XXXX-XXXX.`,"license.save":`Enregistrer la clé`,"license.none":`Aucune clé enregistrée : c'est normal si vous n'êtes pas dans un des cas ci-dessus.`,"license.active":`Clé {key} ({kind})`,"license.until":`jusqu'au {date}`,"license.remove":`Retirer la clé`,"license.removeDesc":`Libère sa place pour un autre serveur.`,"license.onbToggle":`J'ai une clé de licence Entreprise`,"license.onbToggleDesc":`Facultatif, seulement pour les entreprises qui en ont une. Modifiable plus tard dans Réglages → À propos.`,"tint.neutral":`Neutre`,"tint.tinted":`Teinté`,"fonts.group.modern":`Modernes`,"fonts.group.character":`Avec du caractère`,"fonts.group.rounded":`Arrondies`,"fonts.group.serif":`À empattements`,"fonts.group.readable":`Faciles à lire`,"fonts.group.mono":`Monospace`,"fonts.group.system":`Cet appareil`,"density.comfortable":`Confortable`,"density.compact":`Compacte`,"accent.clay":`Orange`,"accent.blue":`Bleu`,"accent.violet":`Pourpre`,"accent.green":`Vert`,"accent.amber":`Jaune`,"accent.rose":`Rouge`,"system.address":`Adresse et fichiers`,"security.change":`Changer le mot de passe`,"security.changeDesc":`Changer le mot de passe déconnecte tous les autres appareils.`,"security.current":`Mot de passe actuel`,"security.currentRequired":`Saisissez votre mot de passe actuel.`,"security.currentWrong":`Le mot de passe actuel est incorrect.`,"security.update":`Mettre à jour`,"security.changed":`Mot de passe modifié`,"security.changedDesc":`Les autres appareils ont été déconnectés.`,"security.sessions":`Appareils connectés`,"security.sessionsDesc":`Les alertes de connexion peuvent être envoyées sur Telegram (Réglages › Telegram).`,"security.status":`Protections`,"security.statusDesc":`Ce qui protège ce serveur, et ce qu’il reste à activer.`,"security.everywhere":`Pour vous déconnecter partout, changez votre mot de passe : tous les cookies de session existants cessent aussitôt de fonctionner.`,"security.app":`Application d'authentification`,"security.appDesc":`Après le mot de passe, un nouveau navigateur demande le code à 6 chiffres d'une application (Aegis, 2FAS, Google Authenticator…). Fonctionne sans Telegram ; avec les deux, l'un ou l'autre suffit. Sortie de secours sans l'interface : maxxing 2fa off sur le serveur.`,"security.appOn":`L'application d'authentification est activée.`,"security.appOff":`L'application d'authentification est désactivée.`,"security.appPwDesc":`Saisissez votre mot de passe actuel pour commencer.`,"security.appScan":`Scannez ce code avec votre application, ou saisissez la clé à la main, puis entrez le code à 6 chiffres qu'elle affiche. Rien ne change tant que ce code n'est pas accepté.`,"security.appOpen":`Ouvrir dans une application de cet appareil`,"security.appKey":`Clé`,"security.appCode":`Code à 6 chiffres`,"security.appBadCode":`Code incorrect.`,"security.appContinue":`Continuer`,"security.appTurnOn":`Activer`,"security.appOffTitle":`Désactiver l'application d'authentification`,"security.appOffDesc":`Saisissez votre mot de passe actuel et un code de l'application (ou un code de secours).`,"security.appOffCode":`Code de l'application ou code de secours`,"security.recovery":`Codes de secours`,"security.recoveryDesc":`{n} restants. Chacun remplace une fois un code de deuxième étape, quand Telegram ou votre application est hors de portée.`,"security.recoveryNew":`Nouveaux codes`,"security.recoveryNewDesc":`Saisissez votre mot de passe actuel. Les codes que vous aviez cessent de fonctionner.`,"security.recoveryTitle":`Vos codes de secours`,"security.recoverySave":`Gardez-les en lieu sûr : ils ne sont affichés qu'une fois. Chaque code sert une seule fois ; les anciens ne fonctionnent plus.`,"security.recoverySaved":`Je les ai enregistrés`,"security.brThis":`Ce navigateur`,"security.brSeen":`Vu {when}`,"security.brDisconnect":`Déconnecter`,"security.brOthers":`Déconnecter tous les autres`,"security.brOthersDone":`Tous les autres navigateurs ont été déconnectés.`,"security.brLegacy":`Navigateurs connectés avant cette version`,"security.brLegacyDesc":`Ils n'ont pas de ligne à eux : « Déconnecter tous les autres » les déconnecte.`,"cdef.defaultModel":`Modèle par défaut`,"cdef.cliDefault":`Défaut de Claude Code`,"cdef.defaultModelHint":`Les sessions affichent le modèle qui a réellement répondu à chaque tour.`,"cdef.autoCompact":`Compaction automatique`,"cdef.autoCompactHint":`Quand un tour se termine avec plus de contexte que ce seuil, Harness résume la session et continue dans un nouveau fil qui part de ce résumé (comme Compacter) : les longues sessions ne renvoient plus tout leur historique, ce qui économise des tokens. L’historique reste affiché.`,"cdef.autoCompactOff":`Désactivée`,"cdef.autoCompactRecommended":`recommandé`,"cdef.idleCompact":`Compacter au retour`,"cdef.idleCompactHint":`Le cache de prompt de Claude dure quelques minutes (une heure au plus). Quand vous écrivez dans une session inactive depuis plus longtemps, avec au moins ce contexte, Harness la résume d'abord et votre message part dans un nouveau fil qui reprend ce résumé : l'historique serait de toute façon renvoyé au prix fort, les tours suivants coûtent donc beaucoup moins. Coût : un tour de résumé (une courte attente) avant la réponse.`,"cdef.smartResume":`Reprise intelligente`,"cdef.smartResumeHint":`Quand vous revenez sur une session dont le cache a expiré (voir ci-dessus) avec au moins ce contexte, ou après 5 minutes ou plus avec le double, Harness fait d'abord résumer la session par Claude pour le message que vous venez d'envoyer : le résumé garde exactement ce dont votre message a besoin (fichiers, commandes, valeurs, plan en cours), puis votre message part dans un fil neuf, bien plus léger. Mesuré sur de vraies reprises : 38 à 67 % de tokens en moins dès 100k, et des détails mieux gardés qu'avec le résumé simple. Désactivé = la règle ci-dessus seule.`,"cdef.protectSecrets":`Protéger les secrets`,"cdef.protectSecretsHint":`Les outils de Claude refusent de lire ou modifier les secrets du serveur (secrets.json) et les clés SSH (~/.ssh), quel que soit le mode de permissions. Cela empêche une instruction cachée dans une page web ou un e-mail de simplement les lire ; un script écrit pour ouvrir le fichier n’est pas bloqué - pour du contenu venu de l’extérieur, préférez un mode plus strict sur ce topic.`,"cdef.shortTitles":`Titres de session courts`,"cdef.shortTitlesHint":`Une nouvelle session est nommée en quelques mots d’après son premier message (sans les « bonjour » ni « tu peux… »). Désactivé : le titre est le début du message. Renommer une session l’emporte toujours.`,"cdef.shortTitlesModel":`Titres écrits par Claude`,"cdef.shortTitlesModelHint":`Le plus petit modèle nomme le sujet (titres plus justes). Un appel rapide par nouvelle session, compté dans votre forfait Claude.`,"cdef.autoUpdate":`Mettre à jour Claude Code automatiquement`,"cdef.autoUpdateHint":`Désactivé par défaut. Activé : quand une version stable plus récente de Claude Code sort (déjà utilisée depuis quelques jours, pas la toute dernière), le serveur l’installe dès que rien n’a tourné depuis 10 minutes (aucun tour, aucun message en attente, aucune tâche planifiée), et revient à la précédente si elle ne démarre pas. Vérifié toutes les 6 heures ; le résultat apparaît dans les notifications.`,"cdef.autoUpdateLast":`Dernière mise à jour : {from} → {to}, {date}`,"cdef.autoUpdateFailed":`Échec de la mise à jour vers {to} ({date})`,"telegram.setup":`Configurer Telegram`,"telegram.setupDesc":`Environ deux minutes. Il vous faut l’application Telegram sur votre téléphone ou votre ordinateur.`,"telegram.sub.bot":`Bot`,"telegram.sub.link":`Liaison`,"telegram.sub.threads":`Fils`,"telegram.bf1":`Dans Telegram, ouvrez`,"telegram.bf2":`Envoyez la commande :`,"telegram.bf3":`Choisissez un nom affiché, puis un identifiant qui se termine par « bot » (par ex. acme_maxxing_bot).`,"telegram.bf4":`BotFather répond avec un jeton du type 123456789:AAH… : copiez-le et collez-le ci-dessous.`,"telegram.token":`Jeton du bot`,"telegram.tokenHint":`Conservé sur ce serveur. Quiconque possède le jeton contrôle le bot.`,"telegram.tokenRequired":`Collez le jeton donné par BotFather.`,"telegram.tokenInvalid":`Telegram a refusé ce jeton.`,"telegram.verify":`Vérifier le jeton`,"telegram.botOk":`Bot vérifié`,"telegram.linkIntro":`Liez maintenant votre compte Telegram : seule la conversation liée peut parler à Harness.`,"telegram.link":`Lier mon Telegram`,"telegram.qr":`QR code pour ouvrir le bot`,"telegram.scan":`Scannez avec votre téléphone`,"telegram.openAndStart":`Ouvrez le bot et appuyez sur Démarrer. Cette page se met à jour toute seule une fois la liaison faite.`,"telegram.openTelegram":`Ouvrir dans Telegram`,"telegram.waiting":`En attente de /start…`,"telegram.manualCode":`Ou envoyez ce message au bot :`,"telegram.chatLinked":`Conversation liée`,"telegram.simpleIntro":`Un seul chat à suivre : écrivez un message pour démarrer une session (le bot demande dans quel topic), répondez à un message pour continuer sa session. Les alertes y arrivent aussi. Un fil par session à la place : Réglages › Telegram › Mode.`,"telegram.threadsIntro":`Chaque session ouverte a son propre fil (plus Crons et Alertes). Archivez une session et son fil disparaît ; écrivez dans le chat principal pour en démarrer une.`,"telegram.created":`{count} fils créés`,"telegram.created#one":`{count} fil créé`,"telegram.topicsOff":`Les fils sont désactivés pour ce bot`,"telegram.topicsOff1":`Ouvrez @BotFather, envoyez /mybots puis choisissez votre bot.`,"telegram.topicsOff2":`Bot Settings › Threaded Mode › activez-le.`,"telegram.topicsOff3":`Revenez ici et appuyez sur « Réessayer ».`,"telegram.noThreads":`Aucun fil pour l’instant.`,"telegram.thread.general":`Général`,"telegram.thread.crons":`Rapports des crons`,"telegram.thread.alerts":`Alertes`,"telegram.thread.feed":`Notifications`,"telegram.status":`État`,"telegram.gateway":`Passerelle`,"telegram.running":`Active`,"telegram.stopped":`Arrêtée`,"telegram.bot":`Bot`,"telegram.chat":`Conversation liée`,"telegram.test":`Envoyer un message de test`,"telegram.testSent":`Message de test envoyé`,"telegram.behaviour":`Comportement`,"telegram.mode":`Mode`,"telegram.modeDesc":`Comment le chat Telegram est organisé. Les agents qui ont l’option Telegram gardent leur propre fil dans tous les modes.`,"telegram.mode.simple":`Simple`,"telegram.mode.simple.desc":`Un seul chat à suivre : les alertes, et vos sessions en réponses. Écrivez un message, choisissez son topic ; répondez à un message pour continuer sa session.`,"telegram.mode.threads":`Un fil par session`,"telegram.mode.threads.desc":`Chaque session ouverte de l’interface web a son propre fil, plus les fils Crons, Alertes et Notifications.`,"telegram.mode.mirror":`Fils + conversations web`,"telegram.mode.mirror.desc":`Un fil par session, où ce que vous écrivez dans l’interface web et les réponses de Harness apparaissent aussi, en silencieux.`,"telegram.mode.needsThreads":`Activez le Threaded Mode du bot dans @BotFather : d’ici là le chat fonctionne en Simple.`,"telegram.mode.recommended":`conseillé`,"telegram.modeConfirm":`Supprimer {count} fils de Telegram ?`,"telegram.modeConfirm#one":`Supprimer {count} fil de Telegram ?`,"telegram.modeConfirmDesc":`Les fils des sessions et les fils Crons, Alertes et Notifications sont supprimés de Telegram, avec leurs messages. Les sessions restent dans l’interface web ; les agents gardent leurs fils.`,"telegram.modeConfirmOk":`Passer en Simple`,"telegram.notifySystem":`Alertes du serveur`,"telegram.notifySystemDesc":`Les problèmes du serveur (disque, services, connexion de Claude, sauvegarde, mises à jour), avec un bouton Vu.`,"telegram.agentThreads":`Fils des agents`,"telegram.agentThreadsDesc":`Les agents qui ont l’option Telegram publient leurs résultats dans leur propre fil.`,"telegram.notifyCrons":`Rapports des crons`,"telegram.notifyCronsDesc":`Publier les résultats des tâches planifiées (selon le réglage de chaque tâche ; les échecs sonnent).`,"telegram.loginAlerts":`Alertes de connexion`,"telegram.loginAlertsDesc":`Message à chaque connexion et alerte sonore après plusieurs mauvais mots de passe.`,"telegram.replyMode":`Réponses`,"telegram.replyModeDesc":`Progression en direct : un message de statut mis à jour pendant que Harness travaille (sa liste de tâches et chaque étape), replié en résumé à la fin. Ou seulement la réponse finale.`,"telegram.reply.final":`Réponse finale`,"telegram.reply.progress":`Progression en direct`,"trash.title":`Corbeille`,"trash.desc":`Fichiers, topics, projets et sessions supprimés. Restaurez-les à leur place, ou supprimez-les définitivement. Les éléments de plus de {days} jours sont effacés automatiquement.`,"trash.kind.file":`fichier`,"trash.kind.folder":`dossier`,"trash.kind.topic":`topic`,"trash.kind.project":`projet`,"trash.kind.session":`session`,"trash.kind.previous_versions":`anciennes versions`,"trash.sessions":`{count} sessions`,"trash.root":`racine du workspace`,"trash.restore":`Restaurer`,"trash.restored":`Restauré dans {path}`,"trash.deleteForever":`Supprimer définitivement`,"trash.deleteConfirm":`Supprimer « {name} » définitivement ?`,"trash.deleteDesc":`Cette action est irréversible.`,"trash.empty":`Vider la corbeille`,"trash.emptyConfirm":`Vider la corbeille ?`,"trash.emptied":`Corbeille vidée`,"trash.none":`La corbeille est vide`,"trash.noneDesc":`Les fichiers, topics et sessions supprimés arrivent ici.`,"packs.title":`Projets de départ`,"packs.desc":`Des projets prêts à l’emploi selon votre activité : chaque topic connaît déjà le métier (un playbook) et vous pose quelques questions à la première session. Aucune fausse donnée. Ajoutez un pack autant de fois que vous voulez : chaque fois c’est un nouveau projet (ecommerce-2 pour une deuxième boutique…). Rien d’existant n’est jamais écrasé.`,"packs.restore":`Réinstaller`,"packs.restored":`{count} fichiers remis`,"packs.nothingMissing":`Rien ne manquait`,"packs.add":`Ajouter`,"packs.added":`Ajouté`,"packs.jobs":`Tâches planifiées créées désactivées : {list}`,"packs.done":`{name} ajouté ({count} topics)`,"packs.doneMany":`{count} projets ajoutés`,"packs.doneMany#one":`{count} projet ajouté`,"packs.all":`Tout installer`,"packs.choose":`Choisir`,"packs.none":`Aucun`,"import.title":`Importer depuis un autre agent`,"import.desc":`Hermes, Claude Code, OpenClaw ou un autre agent : il exporte ce qu’il sait de vous sous forme de projets et de topics, vous déposez le zip ici. Rien d’existant n’est écrasé.`,"import.agent":`Votre agent actuel`,"import.agentFile":`Un agent`,"import.other":`Autre`,"import.more":`Autres imports`,"import.step1":`Copiez ce prompt et envoyez-le à votre agent actuel. Il prépare un zip avec vos projets, topics, mémoire et skills.`,"import.step2":`Déposez le zip qu’il vous donne (ou cliquez pour le choisir). Vous verrez ce qu’il contient avant tout import.`,"import.drop":`Déposez le .zip ici, ou cliquez pour le choisir`,"import.reading":`Lecture du zip…`,"import.projects":`projets`,"import.topics":`topics`,"import.skills":`Skills`,"import.files":`fichiers · {size}`,"import.new":`nouveau`,"import.merge":`existe - fusionné`,"import.rootMemory":`Votre profil et vos préférences (mémoire du workspace)`,"import.aside":`Gardé pour Harness`,"import.neverOverwrite":`Les fichiers de mémoire existants reçoivent une section « Importé », les autres fichiers existants sont conservés et la copie importée est enregistrée à côté.`,"import.secrets":`{count} fichiers refusés : ils contiennent une clé ou un token`,"import.secretsHint":`Ajoutez vos clés dans Réglages → Clés - jamais dans les fichiers de mémoire.`,"import.skipped":`{count} fichiers ignorés`,"import.apply":`Importer`,"import.done":`Importé : {projects} projets, {topics} topics, {files} fichiers.`,"import.mergedInto":`{count} fichiers de mémoire existants ont reçu une section « Importé ».`,"import.finish":`Laisser Harness finir l’import`,"import.finishTitle":`Finir l’import`,"import.finishHint":`Harness range la mémoire importée, crée vos tâches, propose vos tâches planifiées et liste les clés à ajouter.`,"import.finishing":`Harness finit l’import (tâches, tâches planifiées, clés à ajouter) - vous le retrouverez dans Sessions.`,"import.copy":`Copier le prompt`,"import.copied":`Copié`,"import.skillsN":`skills`,"trash.loadFailed":`Impossible de charger la corbeille`,"trash.loadFailedDesc":`Vérifiez votre connexion ou vos droits d’accès, puis réessayez.`,"telegram.threads":`Fils`,"telegram.threadsDesc":`Un par session ouverte, synchronisés automatiquement. Supprimer un fil dans Telegram archive sa session (rien n’est perdu).`,"telegram.threadDays":`Garder un fil pendant`,"telegram.threadDaysDesc":`Les sessions ouvertes inactives plus longtemps perdent leur fil (elles restent dans l’interface web et le retrouvent au prochain message).`,"telegram.days":`{count} jours`,"telegram.threadDaysConfirm":`Supprimer {count} fils ?`,"telegram.threadDaysConfirm#one":`Supprimer {count} fil ?`,"telegram.threadDaysConfirmDesc":`Leurs sessions sont inactives depuis plus longtemps que la nouvelle limite : leurs fils et les messages qu’ils contiennent sont supprimés de Telegram. Les sessions restent dans l’interface web et retrouvent un fil à leur prochain message.`,"telegram.threadDaysConfirmOk":`Supprimer les fils`,"telegram.thread.session":`session`,"telegram.sync":`Synchroniser les fils`,"telegram.unlink":`Déconnecter Telegram`,"telegram.unlinkDesc":`Oublie le jeton du bot, la conversation liée et les fils. Les sessions restent dans l’interface web.`,"telegram.unlinkConfirm":`Déconnecter Telegram ?`,"telegram.twoStepPassword":`La connexion en deux étapes est active : délier, changer de bot ou lier une autre conversation la retire à celle-ci, le mot de passe actuel est donc demandé.`,"telegram.topicsOffDesc":`Tout fonctionne dans la conversation principale. Pour avoir un fil par session, activez le Threaded Mode du bot :`,"telegram.topicsStillOff":`Les fils sont toujours désactivés pour ce bot : vérifiez le Threaded Mode dans @BotFather.`,"telegram.retry":`Réessayer`,"telegram.changeBot":`Changer de bot`,"telegram.changeBotHint":`Collez le jeton d’un autre bot, ou le nouveau jeton de ce bot. Rien ne change tant que le jeton n’est pas vérifié ; un autre bot devra être lié à nouveau.`,"telegram.newLink":`Nouveau lien`,"telegram.expiresIn":`Valable encore {time}`,"telegram.expired":`Ce lien a expiré`,"telegram.expiredDesc":`Un lien est valable 15 minutes. Créez-en un nouveau, puis ouvrez-le dans Telegram.`,"telegram.startEarly":`Vous avez déjà appuyé sur Démarrer dans Telegram ? Ouvrez ce lien (ou scannez le code) maintenant : il envoie le code.`,"telegram.relink":`Lier une autre conversation`,"telegram.relinkDesc":`Ouvrez ce lien depuis le compte Telegram à utiliser : il remplace la conversation liée (le bot reste le même).`,"telegram.newToken":`Nouveau jeton du bot`,"telegram.tokenRejected":`Telegram a refusé le jeton du bot`,"telegram.tokenRejectedDesc":`Le jeton a été révoqué ou remplacé dans @BotFather : le bot ne reçoit plus rien. Collez le nouveau jeton (même bot : la conversation et les fils sont conservés).`,"telegram.removeWebhook":`Supprimer le webhook`,"telegram.err.webhook_set":`Ce bot envoie ses messages à un webhook : un autre programme l’utilise`,"telegram.err.webhookHelp":`Supprimez le webhook pour utiliser le bot ici (l’autre programme ne recevra plus ses messages), ou créez un bot dédié avec @BotFather.`,"telegram.err.conflict":`Un autre programme (n8n, Hermes, OpenClaw…) utilise déjà ce bot : arrêtez-le, ou créez un bot dédié avec @BotFather.`,"telegram.err.webhook_check_failed":`Impossible de vérifier si un autre programme utilise ce bot. Réessayez dans un instant.`,"telegram.err.unreachable":`Telegram est injoignable. Réessayez dans un instant.`,"telegram.pollErrorTitle":`Réception des messages`,"telegram.syncErrorTitle":`Synchronisation des fils`,"telegram.lastPoll":`Dernière réponse de Telegram`,"telegram.never":`jamais`,"telegram.testProblems":`Message de test envoyé, mais :`,"telegram.testNotSent":`Le message de test n’a pas été envoyé :`,"backup.whyTitle":`Pourquoi sauvegarder ?`,"backup.why":`Vos fichiers mémoire sont ce qui rend Harness utile dans la durée. Si ce serveur meurt, une sauvegarde permet à l’installateur de les restaurer sur un nouveau en une minute. Seule une liste blanche de fichiers texte est envoyée, et un détecteur bloque tout ce qui ressemble à une clé.`,"backup.gh1":`Créez un jeton « fine-grained » sur`,"backup.gh2":`Accès aux dépôts : « All repositories » si le dépôt doit être créé pour vous, sinon uniquement le dépôt de sauvegarde.`,"backup.gh3":`Permissions :`,"backup.gh3b":`(la seconde uniquement pour créer le dépôt).`,"backup.gh4":`Générez le jeton, copiez-le et collez-le ci-dessous.`,"backup.repo":`Dépôt`,"backup.repoHint":`proprietaire/nom — il doit être privé.`,"backup.repoInvalid":`Utilisez la forme proprietaire/nom.`,"backup.token":`Jeton GitHub`,"backup.tokenRequired":`Collez le jeton GitHub.`,"backup.create":`Créer le dépôt privé pour moi`,"backup.createHint":`S’il n’existe pas encore. Nécessite la permission Administration.`,"backup.connect":`Vérifier et enregistrer`,"backup.configFailed":`GitHub a refusé l’accès.`,"backup.notPrivate":`Ce dépôt est public : la sauvegarde refuse d’y pousser.`,"backup.connected":`Dépôt de sauvegarde connecté`,"backup.private":`Privé`,"backup.runFirst":`Lancer la première sauvegarde`,"backup.runNow":`Sauvegarder maintenant`,"backup.runOk":`Sauvegarde terminée`,"backup.runOkDesc":`{files} fichiers, commit {commit}.`,"backup.runFailed":`La sauvegarde a échoué`,"backup.repository":`Dépôt`,"backup.repositoryDesc":`Où votre mémoire est envoyée.`,"backup.settings":`Planification et contenu`,"backup.schedule":`Planification`,"backup.scheduleHint":`Expression cron, dans votre fuseau horaire.`,"backup.scheduleInvalid":`Expression cron invalide.`,"backup.include":`Fichiers inclus`,"backup.includeHint":`Les motifs grisés sont toujours inclus. Ajoutez des motifs relatifs à l’espace de travail.`,"backup.always":`Toujours inclus`,"backup.addGlob":`Ajouter un motif`,"backup.history":`Historique`,"backup.historyDesc":`Une restauration place d’abord les fichiers actuels dans la corbeille.`,"backup.noHistory":`Aucune sauvegarde pour l’instant`,"backup.noHistoryDesc":`Les exécutions apparaîtront ici.`,"backup.filesCount":`{count} fichiers`,"backup.filesCount#one":`{count} fichier`,"backup.changedCount":`{count} modifiés`,"backup.restore":`Restaurer`,"backup.restoreTitle":`Restaurer cette sauvegarde ?`,"backup.restoreDesc":`Les fichiers de la liste blanche, les crons et les réglages sont remplacés par cette version. Les fichiers actuels sont d’abord placés dans la corbeille.`,"backup.restored":`{count} fichiers restaurés`,"backup.restored#one":`{count} fichier restauré`,"backup.forget":`Déconnecter la sauvegarde`,"backup.forgetDesc":`Oublie le dépôt et le jeton. Le dépôt lui-même n’est pas supprimé.`,"backup.forgetConfirm":`Déconnecter la sauvegarde ?`,"mcp.whatTitle":`Les serveurs MCP donnent de nouveaux outils à Claude`,"mcp.whatExplain":"Un serveur ajouté pour « Toutes les sessions » est disponible partout ; ajouté à un topic, seulement dans les sessions de ce topic. Les secrets restent dans Réglages → Clés et s’écrivent ${NOM_DE_CLE}. Vous pouvez aussi simplement demander à Claude dans un topic : « connecte le MCP … ».","mcp.servers":`Serveurs MCP`,"mcp.autoTitle":`Chargement`,"mcp.auto":`Charger les serveurs MCP seulement quand une session en a besoin`,"mcp.autoHint":"Chaque serveur chargé coûte des tokens à chaque message et ralentit le début d’un tour. Activé, une session reçoit les serveurs déjà utilisés dans son topic, ceux nommés dans votre message et ceux ajoutés à son topic ; Claude peut en demander un autre (`maxxing mcp load`) et Harness continue tout seul. Si un connecteur claude.ai est nécessaire, tout est chargé, comme avant. Les outils du Navigateur Harness et de vos Appareils sont toujours là quand un tour peut s’en servir.","mcp.serversDesc":`Les serveurs que Claude Code charge dans ce workspace.`,"mcp.checkedAt":`États vérifiés {when}.`,"mcp.check":`Vérifier`,"mcp.checking":`Vérification…`,"mcp.add":`Ajouter un serveur`,"mcp.addDesc":`L’adresse (ou la commande) est donnée par la documentation du service.`,"mcp.empty":`Aucun serveur MCP`,"mcp.emptyDesc":`Ajoutez-en un ici, ou demandez à Claude dans le topic qui en a besoin.`,"mcp.name":`Nom`,"mcp.where":`Où`,"mcp.whereHint":`Toutes les sessions, ou seulement celles d’un topic.`,"mcp.searchTopic":`Chercher un topic`,"mcp.everywhere":`Toutes les sessions`,"mcp.stateCol":`État`,"mcp.type":`Type`,"mcp.typeHttp":`Adresse (URL)`,"mcp.typeStdio":`Programme local`,"mcp.url":`Adresse`,"mcp.command":`Commande`,"mcp.headers":`En-têtes (facultatif)`,"mcp.env":`Variables d’environnement (facultatif)`,"mcp.addLine":`Ajouter une ligne`,"mcp.insertKey":`Insérer une clé du coffre`,"mcp.noKeys":`Aucune clé dans Réglages → Clés`,"mcp.keysHint":"Une clé écrite ${NOM_DE_CLE} est lue dans le coffre au démarrage de la session (elle est fournie aux sessions automatiquement). Les serveurs avec un bouton « Connecter » n’ont pas besoin de clé.","mcp.literalWarn":"Ça ressemble à un jeton écrit en clair : mieux vaut le mettre dans Réglages → Clés et écrire ${NOM_DE_CLE}.","mcp.literal":`jeton en clair`,"mcp.nameInvalid":`Lettres, chiffres, « . », « _ » et « - » seulement.`,"mcp.urlInvalid":`L’adresse commence par https://`,"mcp.commandRequired":`Indiquez la commande qui lance le serveur.`,"mcp.added":`{name} ajouté`,"mcp.addedExposed":`{name} ajouté - clés désormais fournies aux sessions : {keys}`,"mcp.state.connected":`Connecté`,"mcp.state.needs_auth":`À connecter`,"mcp.state.failed":`Erreur`,"mcp.state.pending":`À approuver`,"mcp.state.unknown":`Non vérifié`,"mcp.connect":`Connecter`,"mcp.reconnect":`Reconnecter`,"mcp.connectTitle":`Connecter {name}`,"mcp.connectDesc":`Une seule fois, en quatre étapes : la connexion est ensuite gardée pour toutes les sessions.`,"mcp.preparing":`Préparation de la page de connexion…`,"mcp.step1":`Ouvrez la page de connexion du service`,"mcp.openLogin":`Ouvrir la page de connexion`,"mcp.step2":`Connectez-vous chez {service} et acceptez`,"mcp.step3":`Vous arrivez sur une page d’erreur : c’est normal`,"mcp.step3Desc":`Le service vous renvoie vers une adresse du serveur Harness (« localhost ») que votre navigateur ne peut pas ouvrir : il affiche « Ce site est inaccessible ». La connexion n’est pas finie : le code est dans l’adresse.`,"mcp.browserError":`Ce site est inaccessible - localhost n’autorise pas la connexion.`,"mcp.step3Copy":`Copiez toute l’adresse de la barre d’adresse (cliquez dessus, puis Ctrl+C / ⌘C). Sur téléphone : appui long sur l’adresse, Copier.`,"mcp.step4":`Revenez ici et collez-la`,"mcp.paste":`Coller`,"mcp.pasteDenied":`Le navigateur a refusé : collez avec Ctrl+V / ⌘V dans le champ.`,"mcp.noCode":`Cette adresse ne contient pas « code= » : copiez l’adresse de la page d’erreur, après avoir accepté.`,"mcp.whyTitle":`Pourquoi ce copier-coller ?`,"mcp.whyBody":`Claude Code, qui tourne sur votre serveur, attend la réponse du service sur une adresse locale du serveur. Le service ne peut renvoyer votre navigateur que vers cette adresse, qui n’existe que sur le serveur. En la collant, vous donnez le code à Claude Code, qui termine la connexion. Ça marche quel que soit l’accès (domaine, Tailscale), sans rien d’autre à faire. À faire en quelques minutes : le code expire.`,"mcp.finish":`Terminer`,"mcp.retry":`Réessayer`,"mcp.connected":`{name} est connecté`,"mcp.chatHint":`L'agent a besoin de cette connexion. Une fois faite, dis-lui de réessayer.`,"mcp.chatConnected":`{name} était connecté au dernier contrôle : reconnectez-le si l'agent le demande encore.`,"mcp.remove":`Retirer`,"mcp.removeTitle":`Retirer {name} ?`,"mcp.removeDesc":`Claude n’aura plus ses outils à cet endroit. Les clés du coffre sont gardées.`,"keys.vault":`Coffre`,"keys.vaultDesc":`Les valeurs ne quittent jamais le serveur, sauf si vous les révélez.`,"keys.add":`Ajouter une clé`,"keys.edit":`Modifier la clé`,"keys.dialogDesc":`Enregistrée dans le fichier de secrets du serveur (mode 600).`,"keys.name":`Nom`,"keys.nameHint":`Style variable d’environnement : OPENAI_API_KEY.`,"keys.nameInvalid":`Lettres, chiffres et tirets bas, en commençant par une lettre.`,"keys.value":`Valeur`,"keys.valueKeep":`Laissez vide pour garder la valeur actuelle.`,"keys.valueRequired":`Saisissez une valeur.`,"keys.exists":`Une clé porte déjà ce nom : ouvrez-la avec Modifier pour la changer.`,"keys.note":`Note`,"keys.notePlaceholder":`À quoi elle sert, d’où elle vient`,"keys.noNote":`Sans note`,"keys.expose":`Fournir aux sessions Harness`,"keys.exposeShort":`Exposée`,"keys.unexpose":`Ne plus exposer`,"keys.scope":`Sujets :`,"keys.scopeAll":`tous`,"keys.scopeCount":`{count} sujets`,"keys.scopeCount#one":`{count} sujet`,"keys.scopeChoose":`Choisir`,"keys.scopeClear":`Tous`,"keys.scopeEmpty":`Aucun projet pour l’instant.`,"keys.scopeHint":`Seules les sessions et les tâches planifiées des projets et sujets cochés reçoivent cette clé. Rien de coché : tous les sujets. Les agents gardent leur propre liste de clés.`,"keys.exposeDesc":`Exportée comme variable d’environnement à chaque tour de Harness. Les extensions lisent les clés sans cela : laissez désactivé sauf si les sessions ont besoin de la variable.`,"keys.exposeTitle":`Clés exposées`,"keys.exposeExplain":`Une clé exposée est disponible pour Harness comme variable d’environnement (par ex. $OPENAI_API_KEY) dans chaque session et chaque cron : les scripts peuvent l’utiliser sans que la valeur apparaisse dans un prompt. Harness peut quand même la lire : n’exposez que ce dont les sessions ont besoin.`,"keys.reveal":`Révéler`,"keys.copied":`{name} copiée`,"keys.added":`Clé ajoutée`,"keys.updated":`Clé mise à jour`,"keys.deleteTitle":`Supprimer {name} ?`,"keys.deleteDesc":`Les scripts et sessions qui l’utilisent cesseront de fonctionner.`,"keys.empty":`Aucune clé`,"keys.emptyDesc":`Rangez ici vos clés d’API et jetons plutôt que dans des fichiers.`,"keyfiles.title":`Fichiers`,"keyfiles.desc":`Un keystore, un JSON de compte de service, un certificat : conservés sur le serveur, jamais affichés ni téléchargeables.`,"keyfiles.add":`Ajouter un fichier`,"keyfiles.edit":`Modifier le fichier`,"keyfiles.dialogDesc":`Enregistré sur le serveur dans un dossier privé (mode 600), 1 Mio au maximum.`,"keyfiles.nameHint":`Style variable d’environnement : ANDROID_KEYSTORE. Partagé avec les clés : un nom est une clé ou un fichier.`,"keyfiles.file":`Fichier`,"keyfiles.fileHint":`Tout type de fichier, jusqu’à 1 Mio.`,"keyfiles.fileKeep":`Laissez vide pour garder le fichier actuel ({filename}).`,"keyfiles.choose":`Choisir un fichier`,"keyfiles.replace":`Remplacer le fichier`,"keyfiles.noneChosen":`Aucun fichier choisi`,"keyfiles.expose":`Fournir le chemin aux sessions Harness`,"keyfiles.exposeDesc":`La variable d’environnement {name} contient le chemin du fichier (pas son contenu) dans chaque session Harness et chaque tâche cron shell.`,"keyfiles.exposeTip":"${name} contient le chemin du fichier","keyfiles.added":`Fichier ajouté`,"keyfiles.updated":`Fichier mis à jour`,"keyfiles.deleteTitle":`Supprimer {name} ?`,"keyfiles.deleteDesc":`Le fichier est supprimé du serveur. Les scripts et sessions qui l’utilisent cesseront de fonctionner.`,"keyfiles.empty":`Aucun fichier`,"keyfiles.emptyDesc":`Rangez ici un keystore, un JSON de compte de service ou un certificat plutôt que dans un dossier de projet.`,"keyfiles.safety":`Stockage sûr : les fichiers restent hors de la sauvegarde, de Git et des fichiers mémoire, et rien dans cette page ne permet de les relire. Ce n’est pas une isolation vis-à-vis d’une session : les sessions tournent avec le même utilisateur que le serveur, donc une session à qui l’on donne le chemin peut lire le fichier.`,"keyfiles.err.invalidName":`Majuscules, chiffres et tirets bas, en commençant par une lettre (2 à 64 caractères).`,"keyfiles.err.reservedName":`Ce nom est réservé par le système : choisissez-en un autre.`,"keyfiles.err.nameTaken":`Ce nom est déjà utilisé par une clé texte : choisissez-en un autre.`,"keyfiles.err.nameTakenKey":`Ce nom est déjà utilisé par un fichier : choisissez-en un autre.`,"keyfiles.err.exists":`Un fichier porte déjà ce nom : ouvrez-le avec Modifier pour le remplacer.`,"keyfiles.err.fileRequired":`Choisissez un fichier.`,"keyfiles.err.empty":`Ce fichier est vide.`,"keyfiles.err.tooLarge":`Ce fichier est trop volumineux : 1 Mio au maximum.`,"keyfiles.err.invalidNote":`La description contient des caractères impossibles à enregistrer (caractères de contrôle) : retirez-les.`,"keyfiles.err.unsupportedType":`Le serveur a refusé le format de l’envoi. Rechargez la page et réessayez.`,"keyfiles.clear":`Retirer le fichier choisi`,"keyfiles.keepCurrent":`Garder le fichier actuel`,"features.maxxing":`Mode Maxxing (bêta)`,"features.maxxingDesc":`Un bouton « ⚡ Maxxing » sur la page Sessions (Alt+M), à activer dans chaque navigateur : dès qu’une session finit, elle passe devant, seule, à la place des autres colonnes, pour que vous tapiez la suite tout de suite. Désactivé, vos colonnes reviennent.`,"system.health":`Santé`,"system.healthDesc":`Actualisée toutes les 30 secondes.`,"system.cpuPriorities":`Priorités du processeur`,"system.cpuPrioritiesDesc":`Quand le processeur est plein, ce que vous regardez passe en premier ; les gros travaux (rendus, tâches planifiées) ralentissent un peu, sans jamais s’arrêter.`,"system.disk":`Espace disque`,"system.diskDesc":`Libérez la place prise par les caches, les anciennes versions et les journaux. Vos projets et vos fichiers ne sont jamais touchés.`,"system.diskUsed":`{used} utilisés sur {total} · {free} libres`,"system.cleanup":`Libérer de la place`,"system.cleanupClaude":`Nettoyer avec Claude`,"system.cleanupDesc":`Seulement ce qui revient tout seul ou ce que vous choisissez. Projets, pièces jointes et rendus restent : Nettoyer avec Claude les regarde avec vous.`,"system.cleanupScanning":`Mesure en cours…`,"system.cleanupNothing":`Rien à libérer : tout est déjà propre.`,"system.cleanupRun":`Libérer {size}`,"system.cleanupDone":`{size} libérés`,"system.cleanupFailed":`Certaines parties n’ont pas pu être nettoyées : {parts}`,"system.cleanup.leftovers":`Anciennes versions et restes`,"system.cleanup.leftoversDesc":`Versions précédentes des composants, navigateurs plus utilisés, fichiers temporaires, journaux trop gros.`,"system.cleanup.caches":`Caches de téléchargement`,"system.cleanup.cachesDesc":`Caches uv, npm, pip et npx : retéléchargés la prochaine fois qu’ils servent. Ce qu’un outil en marche utilise reste.`,"system.cleanup.journal":`Journaux du système`,"system.cleanup.journalDesc":`Le journal systemd, réduit à ses 200 derniers Mo.`,"system.cleanup.apt":`Paquets système téléchargés`,"system.cleanup.aptDesc":`Paquets déjà installés par le système (le cache d'apt, dnf ou pacman).`,"system.cleanup.previews":`Aperçus vidéo et vignettes`,"system.cleanup.previewsDesc":`Copies légères des vidéos pour le lecteur et vignettes des fichiers : refaites quand elles sont affichées (un peu de calcul). Une vidéo lue il y a moins de 30 min reste.`,"system.cleanup.trash":`Corbeille de Harness`,"system.cleanup.trashDesc":`Topics, sessions et fichiers supprimés : ils ne pourront plus être restaurés.`,"system.cleanupPrompt":"Fais un audit de l’espace disque de ce serveur et aide-moi à le libérer proprement.\n\n1. État : `df -h` et `free -h`, puis les plus gros dossiers (`du -xh --max-depth=2 / 2>/dev/null | sort -h | tail -40`), et creuse les plus gros. Réglages → Système → Libérer de la place s’occupe déjà des caches de téléchargement, des anciennes versions des composants, du journal système, des paquets apt, des aperçus vidéo et de la corbeille de Harness : laisse-les de côté.\n2. Parcours chaque projet et topic de l’espace de travail : pièces jointes, rendus vidéo et audio, exports, `node_modules`, environnements Python, builds, dépôts git lourds, worktrees oubliés, doublons. Regarde aussi les caches des autres outils (`~/.cache/*`, modèles téléchargés), les journaux et les vieux fichiers de `/tmp`.\n3. Pour chaque gros élément, trouve d’où il vient : quel projet, quel outil ou quelle tâche planifiée l’a créé (dates, contenu, mémoire du topic, crons) et s’il grossit encore.\n4. Donne-moi un tableau trié par taille : chemin, taille, origine, revient tout seul ou non, ce que tu proposes (supprimer, déplacer ailleurs, garder) et la place gagnée.\n5. Ne supprime rien sans mon accord : pose-moi toutes tes questions d’un bloc. Pour ce qui revient sans cesse, propose de corriger la cause (une limite de taille, un nettoyage dans le script ou la tâche qui le produit).\n6. À la fin, note dans la mémoire du bon topic ce qu’on a décidé (ce qu’on garde, ce qui se nettoie).","system.claudeAuth":`Authentification Claude`,"system.notConnected":`Non connecté`,"system.backupAge":`Dernière sauvegarde`,"system.never":`Jamais`,"system.hoursAgo":`il y a {n} h`,"system.failedLogins":`Connexions échouées (1 h)`,"system.load":`Charge moyenne`,"system.services":`Services`,"system.servicesDesc":`Unités systemd utiles à Harness Maxxing.`,"system.disabled":`Désactivé`,"system.start":`Démarrer`,"system.stop":`Arrêter`,"system.restart":`Redémarrer`,"system.stopTitle":`Arrêter {name} ?`,"system.restartTitle":`Redémarrer {name} ?`,"system.serviceConfirm":`Le travail en cours géré par ce service peut être interrompu.`,"system.selfRestart":`L’interface est hors ligne quelques secondes puis se reconnecte seule. Les tours de Harness en cours ne sont pas affectés.`,"system.actionDone":`{name} : fait`,"system.logs":`Journaux`,"system.unit":`Service`,"system.lines":`{n} lignes`,"system.linesLabel":`Nombre de lignes`,"system.noLogs":`Aucune ligne de journal.`,"system.logSearch":`Chercher dans les lignes…`,"system.logLevelLabel":`Niveau`,"system.logLevel.all":`Toutes les lignes`,"system.logLevel.warning":`Avertissements et erreurs`,"system.logLevel.error":`Erreurs seulement`,"system.logSinceLabel":`Période`,"system.logSince.all":`Toute période`,"system.logSince.1h":`Dernière heure`,"system.logSince.24h":`Dernières 24 heures`,"system.logSince.7d":`7 derniers jours`,"system.logMatched":`{shown} lignes affichées sur {matched} trouvées, les plus récentes.`,"system.logTruncated":`Seules les {n} lignes les plus récentes du journal ont été lues : choisissez une période plus courte.`,"system.metrics":`Métriques pour un outil de supervision`,"system.metricsDesc":`Pour Prometheus, Grafana ou un autre outil de supervision que vous avez déjà : tokens, coût, tours, budget, tâches planifiées et santé du serveur, à une seule adresse. Inutile si vous n'en avez pas.`,"system.metricsOn":`Exposer /metrics`,"system.metricsOnDesc":`Lisible seulement avec un jeton secret. Aucun titre de session, message ni fichier n'y figure.`,"system.metricsTokenOnce":`Jeton, affiché cette seule fois : mettez-le maintenant dans votre outil de supervision (Authorization: Bearer …).`,"system.metricsTokenHint":`Le jeton a été affiché à sa création. Perdu ? Créez-en un nouveau : l'ancien cesse de fonctionner.`,"system.metricsNewToken":`Nouveau jeton`,"system.metricsNewTokenConfirm":`Le jeton actuel cesse de fonctionner tout de suite : votre outil de supervision aura besoin du nouveau.`,"system.version":`Version`,"system.upToDate":`À jour`,"system.behind":`{n} mises à jour disponibles`,"system.unknownLatest":`Dernière version inconnue`,"system.unknownLatestDesc":"GitHub est injoignable avec le jeton de mise à jour. Lancez `maxxing update --check` sur le serveur pour voir pourquoi (jeton expiré, pas de réseau).","system.check":`Vérifier`,"system.checkFailed":`La vérification a échoué`,"system.checkedAt":`vérifié {when}`,"system.update":`Mettre à jour`,"system.updateTitle":`Mettre à jour Harness Maxxing ?`,"system.updateDesc":`Télécharge la nouvelle version, installe les dépendances et redémarre le service (environ une minute). Vos données, votre espace de travail et vos extensions sont conservés.`,"system.updating":`Mise à jour…`,"system.restarting":`Redémarrage du serveur…`,"system.updated":`Mise à jour installée`,"system.autoUpdate":`Se mettre à jour seul quand personne n'est là`,"system.autoUpdateHint":`Désactivé par défaut. Activé : quand une nouvelle version est sortie, que personne n'est sur l'interface, que rien ne tourne (ni session, ni job, rien depuis 10 minutes) et que la mise à jour ne touche pas à vos personnalisations, Harness se met à jour seul puis redémarre quelques secondes. Sinon il attend et vous prévient dans les notifications. Les changements qu'une version demande dans votre espace de travail (notes de mise à jour) y sont annoncés aussi, après la mise à jour.`,"system.autoLast":`Dernier passage {when} : {what}`,"system.autoTried":`Dernière mise à jour lancée par lui : {version}, {when}.`,"system.autoRes.started":`mise à jour lancée.`,"system.autoRes.up_to_date":`Harness est à jour.`,"system.autoRes.needs_review":`la nouvelle version a besoin de vous (une personnalisation ou une modification non enregistrée du code). Utilisez le bouton Mettre à jour.`,"system.autoRes.pending":`une mise à jour précédente vous attend, rien n’est tenté tant qu’elle n’est pas réglée.`,"system.autoRes.not_on_branch":`le code est sur un commit placé là exprès, pas sur une branche : il n’est pas touché.`,"system.autoRes.unavailable":`la nouvelle version n’a pas pu être lue (réseau ?). Nouvel essai dans les 30 minutes.`,"system.autoRes.tried_recently":`cette version a déjà été tentée dans les dernières 24 heures. Prochain essai demain.`,"system.autoRes.failed":`la mise à jour n’a pas pu démarrer. Prochain essai demain, ou utilisez le bouton Mettre à jour.`,"system.autoWhy.browser":`en attente, quelqu’un est sur l’interface (un onglet laissé ouvert compte).`,"system.autoWhy.turn":`en attente, une session travaille.`,"system.autoWhy.queue":`en attente, un message attend dans une session.`,"system.autoWhy.aside":`en attente, une question à part est en cours.`,"system.autoWhy.cron":`en attente, un job planifié tourne.`,"system.autoWhy.recent":`en attente, une session a travaillé il y a moins de 10 minutes.`,"system.autoWhy.update":`en attente, une mise à jour est déjà en cours.`,"system.autoWhy.work":`en attente, quelque chose tourne.`,"system.updatedDesc":`Rechargez la page pour utiliser la nouvelle version.`,"system.customs":`{count} personnalisations du code, conservées à chaque mise à jour`,"system.customs#one":`{count} personnalisation du code, conservée à chaque mise à jour`,"system.license":`Licence {key} ({kind}) - {email}`,"system.licenseKind.paid":`payée`,"system.licenseKind.beta":`bêta`,"system.licenseKind.gift":`offerte`,"system.licenseKind.enterprise":`entreprise`,"system.licenseUpdatesUntil":`mises à jour jusqu’au {date}`,"system.licenseUpdatesEnded":`mises à jour terminées le {date} : ce serveur continue sur sa version`,"system.licenseUpdatesForever":`mises à jour incluses`,"system.licenseMoving":`Passage aux mises à jour GitHub en attente : {error}. Nouvel essai toutes les 6 h.`,"system.movedToGit":`Mises à jour depuis GitHub (branche stable) depuis le {date}, comme toutes les installations. Clé {key} gardée.`,"system.pendingConflict":`La mise à jour {version} attend Harness`,"system.pendingConflictDesc":`Vos personnalisations entrent en conflit avec la nouvelle version. Rien n’a changé : la version actuelle continue de tourner. Harness peut les adapter dans le projet system (topic harness).`,"system.pendingRolledBack":`La mise à jour {version} a été annulée`,"system.pendingRolledBackDesc":`La nouvelle version n’a pas démarré : l’ancienne a été remise automatiquement, rien n’est perdu. Demandez à Harness dans le projet system (topic harness) de regarder.`,"system.askClaude":`Demander à Harness`,"features.agentPreview":`Aperçu au survol`,"features.agentPreviewDesc":`Laisser la souris sur un agent d’une liste montre ce qu’il fait. Avec la vue d’ensemble en Space, la carte montre aussi sa salle.`,"push.title":`Notifications mobiles`,"push.desc":`Recevez « Harness a terminé » sur ce téléphone ou cet ordinateur même quand l'application est fermée. La notification ne contient que le titre de la session et le début de la réponse, envoyés par votre propre serveur.`,"push.here":`Notifier sur cet appareil`,"push.hereDesc":`Demande l'autorisation au navigateur et enregistre cet appareil. Chaque tour terminé de vos sessions sonne ensuite ici, sauf celui que vous regardez.`,"push.feed":`Depuis le fil Notifications`,"push.feedDesc":`Ce qui sonne aussi sur les appareils enregistrés. Une demande qui attend votre accord arrive avec Autoriser et Refuser dans la notification (Android et ordinateur ; sur iPhone, un appui l'ouvre). Les alertes sont les avertissements et les erreurs : une tâche qui a échoué, une dépense inhabituelle, un site hors ligne.`,"push.feed.all":`Demandes et alertes`,"push.feed.asks":`Demandes seulement`,"push.feed.off":`Rien`,"push.test":`Envoyer un test`,"push.testSent":`Test envoyé : il doit arriver dans quelques secondes.`,"push.testNone":`Le test n'a pu être envoyé à aucun appareil.`,"push.denied":`Les notifications sont bloquées pour ce site : autorisez-les dans les réglages du navigateur, puis réessayez.`,"push.noWorker":`L'application n'est pas encore prête pour les notifications : rechargez la page et réessayez.`,"push.unsupported":`Ce navigateur ne peut pas recevoir de notifications quand l'application est fermée. Sur Android utilisez Chrome, sur ordinateur Chrome, Edge ou Firefox (HTTPS obligatoire).`,"push.install":`Sur iPhone et iPad, ajoutez d'abord l'application à l'écran d'accueil (Partager, puis Sur l'écran d'accueil), puis ouvrez-la depuis là pour activer ceci.`,"push.device":`Appareil`,"push.thisOne":`cet appareil`,"push.remove":`Retirer cet appareil`,"memory.title":`Nettoyage du second cerveau`,"memory.desc":`Garde chaque memory.md court et bien rangé : doublons fusionnés, contradictions réglées, historique ancien résumé, sections ordonnées. Tourne chaque nuit (tâche « Memory compaction ») et à la demande.`,"memory.cleanNow":`Nettoyer maintenant`,"memory.limit":`Longueur maximale par fichier`,"memory.limitDesc":`Les fichiers plus longs, ou plus lourds (1 Ko pour 10 lignes : 100 lignes = 10 Ko), sont compactés et réorganisés pour tenir dessous (vers 80 %, pour garder de la marge). Un fichier mémoire est renvoyé en entier à Claude à chaque modification : court, il coûte moins et les sessions sont résumées moins souvent.`,"memory.lines":`{count} lignes`,"memory.noLimit":`Aucune limite`,"memory.daily":`Nettoyage nocturne`,"memory.dailyDesc":`La tâche « Memory compaction » tourne à 5 h par défaut : changez son horaire ou coupez-la dans Crons.`,"memory.openCrons":`Ouvrir Crons`,"memory.files":`Fichiers mémoire`,"memory.filesDesc":`Tous les memory.md de l'espace de travail.`,"memory.overCount":`{count} fichiers dépassent {limit} lignes ou {size} - « Nettoyer maintenant » les corrige.`,"memory.overCount#one":`{count} fichier dépasse {limit} lignes ou {size} - « Nettoyer maintenant » le corrige.`,"memory.allUnder":`Tous les fichiers font moins de {limit} lignes et de {size}.`,"memory.none":`Aucun fichier mémoire pour le moment`,"memory.file":`Fichier`,"memory.lineCount":`Lignes`,"memory.size":`Taille`,"memory.started":`Nettoyage lancé`,"memory.startedDesc":`Harness compacte les fichiers mémoire dans une nouvelle session.`,"stats.budget":`Budget du jour`,"stats.budgetDesc":`Un plafond en dollars par jour pour tout le serveur, au prix que Claude Code annonce pour chaque tour (avec un abonnement : ce que les mêmes tours coûteraient avec une clé API).`,"stats.budgetField":`Budget par jour ($)`,"stats.budgetFieldDesc":`0 = pas de budget. Une notification à 80 %, une alerte quand il est atteint. Ensuite, les tâches planifiées et les agents attendent demain ; vos propres messages et « Lancer maintenant » passent toujours.`,"stats.budgetToday":`Aujourd'hui`,"stats.budgetSpent":`{spent} $ sur {limit} $`,"stats.budgetReached":`Budget atteint : les tâches planifiées et les agents attendent demain.`,"stats.limitRetry":`Relancer après la limite d’usage`,"stats.limitRetryDesc":`Une tâche planifiée ou un run d’agent arrêté par la limite d’usage de votre abonnement Claude repart tout seul quand la limite se réinitialise (pas si c’est plus d’un jour après).`,"stats.limitRetryDelay":`Délai après la réinitialisation (secondes)`,"stats.limitRetryDelayDesc":`Combien de temps après l’heure de réinitialisation il repart, de 0 à 3600.`,"stats.alerts":`Alertes`,"stats.alertsDesc":`Une notification quand la dépense sort de l’habitude. Rien n’est arrêté : c’est le rôle d’un budget.`,"stats.alertSpend":`Une journée inhabituelle`,"stats.alertSpendDesc":`Aujourd’hui coûte ce nombre de fois une journée habituelle (la médiane des 14 derniers jours), pour tout le serveur ou pour un agent.`,"stats.alertSpendTimes":`{n} fois`,"stats.alertOff":`Désactivée`,"stats.alertTurn":`Un tour coûteux ($)`,"stats.alertTurnDesc":`Un seul tour coûte au moins ce montant. 0 = pas d’alerte.`,"stats.alertErrors":`Un tour qui échoue en boucle`,"stats.alertErrorsDesc":`Au moins 8 appels d’outils d’un tour ont échoué, et au moins la moitié.`,"stats.quota":`Quota du forfait Claude`,"stats.quotaDesc":`Part utilisée des limites de votre abonnement Claude (la semaine, et la fenêtre de 5 h si votre forfait en a une).`,"stats.quotaEnable":`Afficher l'utilisation du forfait`,"stats.quotaEnableDesc":`Expérimental : lu sur un point d'accès Anthropic non documenté, peut cesser de fonctionner. Ajoute aussi le widget du tableau de bord.`,"stats.fiveHour":`Fenêtre de 5 h en cours`,"stats.plan":`Forfait : Claude {plan}`,"stats.noFiveHour":`Pas de fenêtre de 5 h : le forfait Ultra n'a que la limite de la semaine.`,"stats.sevenDay":`Cette semaine`,"stats.resets":`remise à zéro {at}`,"stats.stale":`Dernières valeurs connues (le point d'accès n'a pas répondu à l'instant).`,"stats.quotaUnavailable":`L'utilisation du forfait n'est pas disponible avec cette méthode de connexion.`,"stats.reason.no_oauth_credentials":`Connectez Claude sur ce serveur (Réglages -> Claude) pour lire l'utilisation du forfait.`,"stats.reason.api_key":`L'utilisation du forfait n'existe qu'avec un abonnement Claude ; ce serveur utilise une clé API.`,"stats.reason.rate_limited":`Anthropic limite la fréquence de lecture de l'utilisation - prochaine lecture {when}.`,"stats.reason.http_401":`La connexion Claude a été refusée : reconnectez-vous (Réglages -> Claude).`,"stats.reason.other":`Impossible de lire l'utilisation du forfait ({code}).`,"stats.nextReading":`Prochaine lecture {when}.`,"stats.tokens":`Tokens`,"stats.tokensDesc":`Comptés sur chaque tour de Harness, sessions archivées comprises. Le graphique par jour démarre avec cette version.`,"stats.empty":`Aucun tour de Harness pour le moment`,"stats.total":`Tokens`,"stats.turns":`{count} tours`,"stats.turns#one":`{count} tour`,"stats.turnsCol":`Tours`,"stats.inOut":`Entrée / sortie`,"stats.cache":`Cache lu / écrit`,"stats.cacheHint":`relectures de contexte peu coûteuses`,"stats.turnStart":`Démarrage d’un tour (médiane)`,"stats.turnStartHint":`première réponse après {first} s · {count} derniers tours`,"stats.perDay":`Tokens par jour (30 jours)`,"stats.groupBy":`Regrouper par`,"stats.byProject":`Projet`,"stats.byTopic":`Topic`,"stats.bySession":`Session`,"stats.byAgent":`Agent`,"stats.costCol":`Coût`,"stats.export":`Télécharger ce tableau, toutes les lignes :`,"stats.exportDays":`Par jour (CSV)`,"about.desc":`Gratuit et fair source : le même code pour tout le monde.`,"about.checkUpdates":`Chercher une mise à jour`,"features.pagesDesc":`Toutes les pages de la barre latérale, dans son ordre. Les pages facultatives peuvent être coupées : la page est masquée, rien n'est effacé.`,"features.thisBrowser":`Ce navigateur`,"features.tabs":`Mode Onglets`,"features.tabsDesc":`Une seule session à l’écran, les sessions ouvertes en onglets au-dessus. Désactivé : mode Zones, les sessions côte à côte. Se change aussi en haut à droite de la page Sessions (Alt+T).`,"features.inSidebar":`Dans la barre latérale`,"features.badges":`Pastilles`,"features.badgesDesc":`Les compteurs à côté des pages de la barre latérale. Désactivez-en une et sa page n’affiche plus ni nombre ni point ; les compteurs restent sur la page elle-même. Une pastille passe au rouge quand l’un de ce qu’elle compte est une erreur.`,"features.badge.home":`Notifications non lues.`,"features.badge.sessions":`Sessions avec une réponse non lue, et celles au travail.`,"features.badge.team":`Messages non lus.`,"features.badge.agents":`Nouveaux résultats et validations en attente.`,"features.alwaysOn":`Toujours là`,"features.page.dashboard":`Votre accueil : widgets, activité du jour, ce qui vous attend.`,"features.page.sessions":`Vos conversations avec Claude, par projet et topic.`,"features.page.files":`Les fichiers du serveur : parcourir, voir, envoyer, télécharger.`,"features.page.agents":`Des aides durables qui vivent dans un topic, chacune avec son rôle et sa mémoire, lancées à la main, à heure fixe, par un webhook ou depuis Telegram, dans un budget par jour.`,"features.page.tasks":`Un tableau des choses à faire (kanban, semaine, calendrier, liste) que Claude lit et met à jour aussi, avec son widget du tableau de bord.`,"features.page.team":`Discuter avec des personnes qui ont leur propre Harness : messages, groupes, sondages et fichiers, de serveur à serveur.`,"features.page.mail":`Vos boîtes mail lues, cherchées et triées ici, et par Claude dans vos sessions.`,"features.page.infra":`Chaque site, base de données, bucket, domaine et serveur, avec son état et l’endroit où il vit.`,"features.page.git":`Les dépôts du serveur et de votre compte GitHub, leurs branches et leurs commits en graphe.`,"features.need.team":`Demande une adresse https sur internet (mode domaine).`,"features.need.mail":`Demande une boîte mail IMAP/SMTP (Gmail avec un mot de passe d’application, OVH…).`,"features.need.infra":`Ce serveur marche tel quel ; Cloudflare et Hostinger demandent leur clé dans`,"features.need.git":`GitHub demande la clé GITHUB_TOKEN dans`,"keys.gitSuggest":`Une clé GitHub est dans le coffre : la page Git montre vos dépôts et leurs graphes.`,"keys.gitSuggestOn":`Afficher la page Git`,"appearance.theme":`Thème`,"appearance.themeDesc":`L’allure de toute l’interface, widgets compris. Ses couleurs et polices se règlent juste en dessous.`,"appearance.default":`par défaut`,"appearance.solidDesc":`Couleurs pleines, nettes et calmes.`,"appearance.glassDesc":`Barres, menus et fenêtres translucides sur un fond aux couleurs de votre accent.`,"appearance.options":`Options de {name}`,"appearance.optionsDesc":`Sombre ou clair, la couleur d’accent, le fond et les polices.`,"appearance.by":`par {name}`,"appearance.onSolid":`sur Mat`,"appearance.onGlass":`sur Verre`,"appearance.installedDesc":`Thème installé.`,"appearance.unusable":`Thèmes inutilisables :`,"appearance.moreThemes":`D’autres thèmes : faits pour vous ou pris dans Community, installés par Harness.`,"appearance.ask":`Demander à Harness`,"appearance.askPrompt":`J’aimerais un nouveau thème pour Harness Maxxing (skill maxxing-theme). Voici ce que j’ai en tête : `,"appearance.fixedMode":`Ce thème n’existe que dans ce mode.`,"appearance.ownAccent":`Fixée par ce thème.`,"appearance.css":`CSS avancé`,"appearance.cssDesc":`Règles de style en plus de ce thème. Contrairement à ses couleurs, elles peuvent mal s’afficher après une mise à jour : coupez-les ici si quelque chose semble cassé.`,"appearance.cssStale":`Coupé : une mise à jour a changé l’interface. Harness le vérifie puis le rallume.`,"appearance.cssVerify":`Demander à Harness de vérifier`,"appearance.cssVerifyPrompt":`Le CSS avancé de mon thème {id} a été coupé par une mise à jour. Vérifie-le avec l’interface actuelle (skill maxxing-theme), corrige-le si besoin, puis rallume-le.`,"appearance.layout":`Disposition`,"appearance.layoutDesc":`Espacement, mise en page téléphone ou ordinateur, et premier écran sur téléphone.`,"security.privacy":`Confidentialité`,"security.privacyDesc":`Le mode présentation masque vos données pendant un partage d’écran (l’icône œil en bas de la barre latérale).`,"about.version":`Version {version}`,"about.community":`Communauté`,"emoji.pick":`Choisir un emoji`,"emoji.search":`Chercher un emoji`,"emoji.none":`Aucun emoji trouvé`,"emoji.clear":`Retirer l'emoji`,"about.contact":`Rester en contact`,"import.restore":`Une sauvegarde de la mémoire`,"import.restoreDesc":`Vous changez de serveur : restaurez la sauvegarde de l’ancien depuis son dépôt GitHub.`,"import.agentDesc":`Un fichier d’agent (.md, format Claude Code) : page Agents -> Nouvel agent -> Importer.`,"skills.where.workspace":`Workspace`,"skills.where.user":`Serveur`,"skills.slashOnly":`seulement avec /{name}`,"skills.open":`Ouvrir`,"skills.edit":`Modifier avec Claude`,"skills.editPrompt":`Modifie la skill {name} ({path}) : `,"skills.publish":`Partager avec la communauté`,"skills.publishPrompt":`Prépare la skill {name} ({path}) pour la communauté Harness Maxxing, en suivant https://harness-maxxing.com/community/publish.md : vérifie qu’elle ne contient ni données personnelles, ni chemins, ni secrets, puis dis-moi quoi envoyer.`,"skills.search":`Chercher une skill`,"skills.mine":`Vos skills`,"skills.mineDesc":`Dans ~/.claude/skills (toutes les sessions), dans le workspace, ou dans un projet ou un topic (ses sessions seulement).`,"skills.new":`Nouvelle skill`,"skills.newPrompt":`Crée une skill (dans le bon dossier .claude/skills) qui `,"skills.emptyShipped":"Les skills livrées avec Harness ne sont pas sur ce serveur. `maxxing update` les réinstalle.","skills.noMatch":`Aucune skill ne correspond.`,"skills.empty":`Aucune skill à vous pour l’instant`,"skills.emptyDesc":`Demandez à Claude d’en écrire une quand vous refaites souvent le même type de tâche.`,"skills.shipped":`Fournies avec Harness`,"skills.shippedDesc":`Rafraîchies à chaque mise à jour : ouvrez-les pour les lire, ne les modifiez pas.`,"pkg.from":`Installé depuis {source} le {date}`,"pkg.on":`Installé le {date}`,"pkg.modified":`fichiers modifiés depuis l’installation`,"pkg.section":`Communauté`,"pkg.sectionDesc":`Extensions, thèmes et skills partagés par d'autres utilisateurs : lisez ce que chacun fait, puis installez-le.`,"pkg.catalogue":`Catalogue de la communauté`,"pkg.catalogueDesc":`Lu sur harness-maxxing.com quand vous ouvrez cette page. Chaque fiche est téléchargée au commit qui a été relu.`,"pkg.site":`Site web`,"pkg.tab.extension":`Extensions`,"pkg.tab.theme":`Thèmes`,"pkg.tab.skill":`Skills`,"pkg.type.widget":`Widget`,"pkg.type.page":`Page`,"pkg.type.view":`Vue des agents`,"pkg.serverCode":`Code serveur`,"pkg.details":`Détails`,"pkg.installed":`Installé`,"pkg.checkInstall":`Vérifier et installer`,"pkg.unreachable":`Le catalogue est injoignable`,"pkg.empty":`Rien ici pour l'instant`,"pkg.emptyDesc":`Personne n'en a encore partagé de ce type.`,"pkg.reportDesc":`Ce qu'il ferait sur ce serveur, lu au commit {commit} sans rien exécuter.`,"pkg.runsServer":`Exécute du code sur ce serveur`,"pkg.runsBrowser":`Aucun code ne tourne sur ce serveur`,"pkg.files":`{n} fichiers`,"pkg.notVerdict":`Une aide à la lecture, pas un verdict : le scan fait ce qu'il peut et peut passer à côté de quelque chose. Vous êtes responsable de ce que vous installez.`,"pkg.disclaimer":`Les fiches sont écrites par d'autres utilisateurs. Nous relisons et scannons chacune, du mieux possible, mais une vérification peut passer à côté de quelque chose : vous êtes responsable de ce que vous installez, et Harness Maxxing n'est pas responsable de ce que fait une fiche.`,"pkg.readIt":`J'ai lu les points en rouge et je veux l'installer.`,"pkg.install":`Installer`,"pkg.replace":`Remplacer celui qui est installé`,"pkg.done":`{name} est installé`,"skills.community":`Des skills partagées par d’autres utilisateurs :`,"features.page.jarvis":`Un seul assistant à qui parler : il crée projets et topics, confie le travail aux sessions et aux agents, reçoit leurs résultats et continue la conversation, avec un brief du matin et une mémoire qu’il range chaque nuit.`,"features.need.jarvis":`Consomme plus de votre forfait Claude que des sessions seules : chaque réponse qui revient d’une session est un tour de Jarvis en plus, avec un brief le matin et une passe de nuit (Sonnet, sautée un jour calme). Coupez le brief ou la passe de nuit dans ses réglages pour dépenser moins.`};export{e as default};